import type { EegAnalysis } from './eeg-analysis';

/**
 * R6 verification bridge.
 * Reference files are generated by the locally run MNE script, not uploaded.
 * The application cannot attest whether a person used the same original EDF.
 */
export const R6_METHOD = 'mriphi-r5-hann-symmetric-welch-v1' as const;
export type R6Band = { key: string; power: number | null; relativePercent: number | null };

export type R6Request = {
  schema: 'mriphi-r6-verification-request-v1';
  method: typeof R6_METHOD;
  datasetKind: 'synthetic' | 'local';
  channelIndex: number;
  sampleRateHz: number;
  startSample: number;
  sampleCount: number;
  startSeconds: number;
  fftSize: number;
  welchSegments: number;
  bands: R6Band[];
  peakFrequencyHz: number;
  acRms: number;
  peakToPeak: number;
  disclaimer: string;
};

export type R6Reference = {
  schema: 'mriphi-r6-mne-reference-v1';
  method: typeof R6_METHOD;
  channelIndex: number;
  sampleRateHz: number;
  startSample: number;
  sampleCount: number;
  fftSize: number;
  welchSegments: number;
  bands: R6Band[];
  peakFrequencyHz: number;
  acRms: number;
  peakToPeak: number;
  engine: string;
};

export type R6Check = {
  name: string;
  outcome: 'PASS' | 'FAIL';
  observed: string;
  reference: string;
};

export type R6Comparison = {
  result: 'MATCH' | 'DIFFER';
  checks: R6Check[];
  summary: string;
  caveat: string;
};

function finite(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
function show(value: number | null): string {
  return value === null ? 'N/A' : Number(value.toPrecision(8)).toString();
}
function near(a: number, b: number, relative = 0.01, absolute = 1e-10) {
  return Math.abs(a - b) <= Math.max(absolute, relative * Math.max(Math.abs(a), Math.abs(b)));
}
function peakFrequency(analysis: EegAnalysis): number {
  let index = 0;
  for (let i = 1; i < analysis.psd.length; i++) {
    const f = analysis.frequenciesHz[i];
    if (f > 45 || f > analysis.sampleRateHz / 2) break;
    if (analysis.psd[i] > analysis.psd[index]) index = i;
  }
  return analysis.frequenciesHz[index];
}

export function createR6Request(analysis: EegAnalysis): R6Request {
  return {
    schema: 'mriphi-r6-verification-request-v1',
    method: R6_METHOD,
    datasetKind: analysis.provenance,
    channelIndex: analysis.channelIndex,
    sampleRateHz: analysis.sampleRateHz,
    startSample: Math.round(analysis.startSeconds * analysis.sampleRateHz),
    sampleCount: analysis.analyzedSamples,
    startSeconds: analysis.startSeconds,
    fftSize: analysis.fftSize,
    welchSegments: analysis.welchSegments,
    bands: analysis.bands.map(({ key, power, relativePercent }) => ({ key, power, relativePercent })),
    peakFrequencyHz: peakFrequency(analysis),
    acRms: analysis.acRms,
    peakToPeak: analysis.peakToPeak,
    disclaimer: 'Browser-computed aggregates, not independently verified. No raw samples, patient metadata or filename. An independent run on the same original EDF is needed.',
  };
}

function parseBand(value: unknown): R6Band {
  if (!value || typeof value !== 'object') throw Error('Reference bands contain an invalid item.');
  const band = value as Record<string, unknown>;
  if (typeof band.key !== 'string' || band.key.length > 30 ||
      !(band.power === null || finite(band.power)) ||
      !(band.relativePercent === null || finite(band.relativePercent))) {
    throw Error('Reference band is malformed.');
  }
  return { key: band.key, power: band.power as number | null, relativePercent: band.relativePercent as number | null };
}

export function parseR6Reference(text: string): R6Reference {
  if (text.length > 100_000) throw Error('Reference JSON exceeds 100 KB limit.');
  let value: unknown;
  try { value = JSON.parse(text); } catch { throw Error('Reference file must contain valid JSON.'); }
  if (!value || typeof value !== 'object') throw Error('Reference root must be an object.');
  const item = value as Record<string, unknown>;
  if (item.schema !== 'mriphi-r6-mne-reference-v1' || item.method !== R6_METHOD) {
    throw Error('Expected an R6 MNE reference JSON using the matching analysis method.');
  }
  for (const key of ['channelIndex','sampleRateHz','startSample','sampleCount','fftSize','welchSegments','peakFrequencyHz','acRms','peakToPeak']) {
    if (!finite(item[key])) throw Error('Reference metric missing or nonfinite: ' + key);
  }
  if (!Array.isArray(item.bands) || item.bands.length !== 5) throw Error('Expected five conventional frequency bands.');
  if (typeof item.engine !== 'string' || !item.engine.startsWith('MNE-Python ')) {
    throw Error('Reference must declare the MNE-Python implementation.');
  }
  return {
    schema: 'mriphi-r6-mne-reference-v1', method: R6_METHOD,
    channelIndex: item.channelIndex as number, sampleRateHz: item.sampleRateHz as number,
    startSample: item.startSample as number, sampleCount: item.sampleCount as number,
    fftSize: item.fftSize as number, welchSegments: item.welchSegments as number,
    peakFrequencyHz: item.peakFrequencyHz as number, acRms: item.acRms as number,
    peakToPeak: item.peakToPeak as number, bands: item.bands.map(parseBand),
    engine: item.engine,
  };
}

/**
 * Strict metadata gates first; numerical checks within documented 1% relative
 * or tiny floor tolerance. Matching cannot establish source-file authenticity.
 */
export function compareR6(request: R6Request, reference: R6Reference): R6Comparison {
  const checks: R6Check[] = [];
  const add = (name: string, pass: boolean, observed: string, expected: string) =>
    checks.push({ name, outcome: pass ? 'PASS' : 'FAIL', observed, reference: expected });
  for (const key of ['channelIndex', 'startSample', 'sampleCount', 'fftSize', 'welchSegments'] as const) {
    add(key, request[key] === reference[key], String(request[key]), String(reference[key]));
  }
  add('sampleRateHz', near(request.sampleRateHz, reference.sampleRateHz, 1e-9, 1e-9),
    show(request.sampleRateHz), show(reference.sampleRateHz));
  add('peakFrequencyHz', near(request.peakFrequencyHz, reference.peakFrequencyHz, 0, request.sampleRateHz / request.fftSize * 0.01),
    show(request.peakFrequencyHz), show(reference.peakFrequencyHz));
  add('acRms', near(request.acRms, reference.acRms), show(request.acRms), show(reference.acRms));
  add('peakToPeak', near(request.peakToPeak, reference.peakToPeak), show(request.peakToPeak), show(reference.peakToPeak));
  request.bands.forEach((band, index) => {
    const other = reference.bands[index];
    add(band.key + ' band identity', other?.key === band.key, band.key, other?.key ?? '(missing)');
    const powerMatch = (band.power === null && other?.power === null) ||
      (band.power !== null && other?.power !== null && near(band.power, other.power));
    add(band.key + ' power', powerMatch, show(band.power), show(other?.power ?? null));
    const percentMatch = (band.relativePercent === null && other?.relativePercent === null) ||
      (band.relativePercent !== null && other?.relativePercent !== null &&
        near(band.relativePercent, other.relativePercent, 0.01, 0.01));
    add(band.key + ' relative %', percentMatch, show(band.relativePercent), show(other?.relativePercent ?? null));
  });
  const match = checks.every((check) => check.outcome === 'PASS');
  return {
    result: match ? 'MATCH' : 'DIFFER', checks,
    summary: match
      ? 'Numerical cross-check matched the imported reference within the stated tolerances.'
      : 'One or more numerical or identity checks differed. Review file selection, channel, time window, calibration and algorithm.',
    caveat: 'MATCH confirms agreement with an imported JSON calculation, not the authenticity of that JSON, the identity of the source EDF, signal quality, any neural interpretation or clinical validity.',
  };
}
